solution_files.leap.tcl:
#!/usr/bin/env tclsh
package require Tcl 8.6

# Says whether the year is a leap year.
proc isLeapYear {year} {
    expr {$year % 4 == 0 && ($year % 100 != 0 || $year % 400 == 0)}
}

